using System;
using UnityEngine;
using UnityEditor;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            if (EditorApplication.isCompiling)
                throw new Exception("Editor is compiling");
            var t = Type.GetType("GuildUiAssetImport, MmorpgClient.Guild.Editor", true);
            t.GetMethod("ImportApproved").Invoke(null, null);
            result.Log("Imported guild sprites through official Unity MCP");
        }
    }
}
